import ta5g_iphy
import socket
import ta5g_enb
import time

from glob import glob
import xml.etree.ElementTree as ET
from contextlib import contextmanager
from robot.api import logger
from robot.errors import ExecutionFailed
from robot.libraries.BuiltIn import BuiltIn
from ute_fsmaccess import ute_fsmaccess
from ute_fsmaccess.exception import SSHExecutionError
from ute_async import ute_async
from ta5g_global_var import IPHY0_LMP_IP, ENB0_LMP_IP, ENB_SUBDIR
from config_translator import ConfigTranslator
from taf.config.testline.testline import TestLine
from taf.hw.pdu import pdu
from ta5g_interface_tools.robot_variables import get_robot_temp_dir
from ta5g_admin_operations import ta_admin_interface
from .tl_console_sanity import saneconsole
from ta5g_admin_operations import ta5g_admin_operations


class ta5g_testline_action(object):
    def __init__(self):
        self._ute_fsmaccess_instance = ute_fsmaccess()
        self._pdu_interface = pdu()

    @contextmanager
    def ute_fsm_configurator(self, remote_host=None, host=ENB0_LMP_IP):
        """
        :param remote_host:
        :param host:
        :return:
        """
        try:
            self._ute_fsmaccess_instance.setup_enb_fsm_access(remote_host=remote_host, host=host)
            yield self._ute_fsmaccess_instance
        finally:
            self._ute_fsmaccess_instance.teardown_enb_fsm_access()

    def trigger_site_reset(self, remote_host=None, timeout=300):
        temp_dir = get_robot_temp_dir()
        ta5g_iphy.ta5g_iphy().get_iphy_xml_file(output_filepath='{}/iphy.xml'.format(temp_dir))
        iphy_xml = ET.parse(source='{}/iphy.xml'.format(temp_dir))
        with ta_admin_interface.get_admin_interface(remote_host=remote_host) as admin_client:
            admin_client.reset_site(wait_for_reconnection=False)
        AutoRebootOnLinkDown_element = iphy_xml.find(".//AutoRebootOnLinkDown")
        if AutoRebootOnLinkDown_element is not None:
            AutoRebootOnLinkDown_text = AutoRebootOnLinkDown_element.text.lower()
            if AutoRebootOnLinkDown_text not in ["true", "t", "1", "yes", "y", "on"]:
                self.call_ap_console_reboot(remote_host=remote_host)
        else:
            logger.debug("Warning: AutoRebootOnLinkDown element not found in XML.")
        self.wait_till_testline_lmp_interfaces_become_unpingable(remote_host=remote_host, timeout_s=timeout)

    def trigger_site_reset_aic_vcu(self, waiting_for_f1=True):
        with ta5g_admin_operations().connect_to_vcu_aic() as vcu_connection:
            vcu_connection.reset_cu()
        time.sleep(60)
        self.wait_for_gnb_icmp_echo_reply_vcu_aic(timeout=300)
        self.wait_for_ap_icmp_echo_reply_and_ssh_service_availability()
        if waiting_for_f1:
            ta5g_admin_operations().wait_for_f1_links_to_be_available_aic()

    def trigger_site_reset_aic_vdu(self, vdu=1, timeout=300):
        tl = BuiltIn().get_variable_value("${tl}")
        host = tl.gnbs[0].dus[vdu - 1].oam_http_connection_details.addr
        with ta5g_admin_operations().connect_to_vdu_aic(host) as vdu_connection:
            vdu_connection.reset_vdu()
        time.sleep(60)
        self.wait_for_gnb_icmp_echo_reply_vdu_aic(host=host, timeout=timeout)
        self.wait_for_ap_icmp_echo_reply_and_ssh_service_availability()

    def trigger_vdu_lock_aic(self, du_id=1):
        if not isinstance(du_id, list):
            du_id = [str(du_id)]
        with ta5g_admin_operations().connect_to_vcu_aic() as vcu_connection:
            vcu_connection.lock_du(du_id=du_id)

    def trigger_vdu_unlock_aic(self, du_id=1):
        if not isinstance(du_id, list):
            du_id = [str(du_id)]
        with ta5g_admin_operations().connect_to_vcu_aic() as vcu_connection:
            vcu_connection.unlock_du(du_id=du_id)

    def call_testline_console_reboot(self, iphy_lmp_ip=IPHY0_LMP_IP, remote_host=None, alias='alias'):
        """
        :param remote_host:
        :param iphy_lmp_ip:
        :param alias:
        :return:
        """
        self.call_gnb_console_reboot(remote_host=remote_host, alias=alias)
        self.call_ap_console_reboot(iphy_lmp_ip=iphy_lmp_ip, remote_host=remote_host, alias=alias)

    def call_gnb_console_reboot(self, remote_host=None, alias='alias'):
        """
        :param remote_host:
        :param alias:
        :return:
        """
        try:
            self._ute_fsmaccess_instance.setup_enb_fsm_access(host=ENB0_LMP_IP, remote_host=remote_host, alias=alias + ENB_SUBDIR)
            self._ute_fsmaccess_instance.start_command_on_enb(cmd='reboot', alias=alias + ENB_SUBDIR)
            self._ute_fsmaccess_instance.teardown_enb_fsm_access(alias=alias + ENB_SUBDIR)
        except SSHExecutionError as error:
            logger.info('ta5g_testline_action: exception = {}'.format(error), also_console=True)

    def call_ap_console_reboot(self, iphy_lmp_ip=IPHY0_LMP_IP, remote_host=None, alias='alias'):
        """
        :param remote_host:
        :param iphy_lmp_ip:
        :param alias:
        :return:
        """
        try:
            self._ute_fsmaccess_instance.setup_wts_fsm_access(
                remote_host=remote_host, host=iphy_lmp_ip, alias=alias + 'iphy'
            )
            self._ute_fsmaccess_instance.start_command_on_wts(cmd='reboot', alias=alias + 'iphy')
            self._ute_fsmaccess_instance.teardown_wts_fsm_access(alias=alias + 'iphy')
        except SSHExecutionError as error:
            logger.info('ta5g_testline_action: exception = {}'.format(error), also_console=True)

    def multi_enb_software_reset_testline_and_wait_for_lmp_interfaces(self, remote_host_list):
        """
        :param remote_host_list:
        :return:
        """
        env_count = len(remote_host_list)
        for env_id in range(0, env_count):
            self.call_testline_console_reboot(
                remote_host=remote_host_list[env_id], iphy_lmp_ip=IPHY0_LMP_IP[:-1] + str(env_id + 1)
            )

    def wait_for_testline_icmp_echo_replies_and_ssh_services(
            self, remote_host=None, iphy_lmp_ip=IPHY0_LMP_IP, timeout_s=480
    ):
        self._wait_for_enb_and_iphy(remote_host, iphy_lmp_ip, timeout_s, 'Wait Until Host Is Available')
        self._wait_for_enb_and_iphy(
            remote_host=remote_host,
            iphy_lmp_ip=iphy_lmp_ip,
            timeout=timeout_s,
            method='Wait For Host Ssh',
            fallback_prompt='#',
        )

    def wait_for_gnb_icmp_echo_reply_vcu_aic(self, remote_host=None, timeout=120):
        self._ute_fsmaccess_instance.wait_until_host_is_available('192.168.100.129', timeout=timeout,
                                                                  remote_host=remote_host)

    def wait_for_gnb_icmp_echo_reply_vdu_aic(self, host=ENB0_LMP_IP, remote_host=None, timeout=120):
        self._ute_fsmaccess_instance.wait_until_host_is_available(host, timeout=timeout,
                                                                  remote_host=remote_host)

    def wait_till_testline_lmp_interfaces_become_unpingable(
            self, remote_host=None, iphy_lmp_ip=ENB0_LMP_IP, timeout_s=100
    ):
        self._wait_for_enb_and_iphy(remote_host, iphy_lmp_ip, timeout_s, 'Wait Until Host Is Unavailable')

    def wait_for_gnb_icmp_echo_reply_and_ssh_service_availability(self, remote_host=None, timeout=120):
        self._ute_fsmaccess_instance.wait_until_host_is_available(ENB0_LMP_IP, timeout=timeout, remote_host=remote_host)
        self._ute_fsmaccess_instance.wait_for_host_ssh(
            ENB0_LMP_IP, timeout=timeout, remote_host=remote_host, fallback_prompt='#'
        )

    def wait_for_ap_icmp_echo_reply_and_ssh_service_availability(self, remote_host=None, timeout=120):
        self._ute_fsmaccess_instance.wait_until_host_is_available(
            IPHY0_LMP_IP, timeout=timeout, remote_host=remote_host
        )
        self._ute_fsmaccess_instance.wait_for_host_ssh(
            IPHY0_LMP_IP, timeout=timeout, remote_host=remote_host, fallback_prompt='#'
        )

    @staticmethod
    @saneconsole
    def _wait_for_enb_and_iphy(remote_host, iphy_lmp_ip, timeout, method, **kwargs):
        alias_enb = 'enb_lmp_ping'
        alias_iphy = 'iphy_lmp_ping'
        _async = ute_async()
        _async.start_async(
            'ute_fsmaccess',
            '{}'.format(method),
            iphy_lmp_ip,
            remote_host=remote_host,
            timeout=timeout,
            alias=alias_iphy,
            **kwargs
        )
        _async.start_async(
            'ute_fsmaccess',
            '{}'.format(method),
            ENB0_LMP_IP,
            remote_host=remote_host,
            timeout=timeout,
            alias=alias_enb,
            **kwargs
        )
        _async.wait_for_async_result(alias=alias_iphy, timeout=timeout)
        _async.wait_for_async_result(alias=alias_enb, timeout=timeout)
        _async.stop_async(alias=alias_iphy)
        _async.stop_async(alias=alias_enb)

    def multi_enb_wait_till_testline_lmp_interfaces_become_pingable(self, remote_host_list):
        """
        :param remote_host_list:
        :return:
        """
        env_count = len(remote_host_list)
        for env_id in range(0, env_count):
            self.wait_for_testline_icmp_echo_replies_and_ssh_services(
                remote_host=remote_host_list[env_id], iphy_lmp_ip=IPHY0_LMP_IP[:-1] + str(env_id + 1), timeout_s=480
            )

    def multi_enb_wait_till_testline_lmp_interfaces_become_unpingable(self, remote_host_list):
        """
        :param remote_host_list:
        :return:
        """
        env_count = len(remote_host_list)
        for env_id in range(0, env_count):
            self.wait_till_testline_lmp_interfaces_become_unpingable(
                remote_host=remote_host_list[env_id], iphy_lmp_ip=IPHY0_LMP_IP[:-1] + str(env_id + 1), timeout_s=100
            )

    def get_file(self, function_name, filepath, remote_host=None):
        """
        :param function_name:
        :param filepath:
        :param remote_host:
        :return:
        """
        self._ute_fsmaccess_instance.setup_enb_fsm_access(host=ENB0_LMP_IP, remote_host=remote_host)
        getattr(self._ute_fsmaccess_instance, function_name)(destination=filepath)
        self._ute_fsmaccess_instance.teardown_enb_fsm_access()

    def put_file(self, function_name, filepath, remote_host=None):
        """
        :param function_name:
        :param filepath:
        :param remote_host:
        :return:
        """
        self._ute_fsmaccess_instance.setup_enb_fsm_access(host=ENB0_LMP_IP, remote_host=remote_host)
        getattr(self._ute_fsmaccess_instance, function_name)(source=filepath)
        self._ute_fsmaccess_instance.teardown_enb_fsm_access()

    def get_testline_pdu_details(self, testline_config_index):
        """
        :param testline_config_index:
        :return:
        """
        tl = BuiltIn().get_variable_value("${tl}")
        if tl is None:
            self._determine_testline_config_directory_and_import_variables()
            tl = BuiltIn().get_variable_value("${tl}")
            if tl is None:
                raise ExecutionFailed("Variable tl has not been set")
        if isinstance(tl, TestLine):
            tl = ConfigTranslator().translate(tl)

        enb_pdu_ip = tl.fsm[testline_config_index + 1].pdu.addr
        enb_pdu_type = tl.fsm[testline_config_index + 1].pdu.device
        enb_pdu_port = tl.fsm[testline_config_index + 1].pdu.port

        iphy_pdu_ip = tl.iphy[testline_config_index + 1].pdu.addr
        iphy_pdu_type = tl.iphy[testline_config_index + 1].pdu.device
        iphy_pdu_port = tl.iphy[testline_config_index + 1].pdu.port

        return [enb_pdu_ip, enb_pdu_type, enb_pdu_port, iphy_pdu_ip, iphy_pdu_type, iphy_pdu_port]

    def turn_on_testline(self, testline_config_index=0):
        """
        :param testline_config_index:
        :return:
        """
        (
            enb_pdu_ip,
            enb_pdu_type,
            enb_pdu_port,
            iphy_pdu_ip,
            iphy_pdu_type,
            iphy_pdu_port,
        ) = self.get_testline_pdu_details(testline_config_index)

        self._pdu_interface.setup_pdu(alias='fsm', host=str(enb_pdu_ip), model=str(enb_pdu_type))
        self._pdu_interface.setup_pdu(alias='iphy', host=str(iphy_pdu_ip), model=str(iphy_pdu_type))

        self._pdu_interface.power_on(pdu_device='fsm', port=int(enb_pdu_port))
        self._pdu_interface.power_on(pdu_device='iphy', port=int(iphy_pdu_port))

    def turn_off_testline(self, testline_config_index=0):
        """
        :param testline_config_index:
        :return:
        """
        (
            enb_pdu_ip,
            enb_pdu_type,
            enb_pdu_port,
            iphy_pdu_ip,
            iphy_pdu_type,
            iphy_pdu_port,
        ) = self.get_testline_pdu_details(testline_config_index)

        self._pdu_interface.setup_pdu(alias='fsm', host=str(enb_pdu_ip), model=str(enb_pdu_type))
        self._pdu_interface.setup_pdu(alias='iphy', host=str(iphy_pdu_ip), model=str(iphy_pdu_type))

        self._pdu_interface.power_off(pdu_device='fsm', port=int(enb_pdu_port))
        self._pdu_interface.power_off(pdu_device='iphy', port=int(iphy_pdu_port))

    @saneconsole
    def reset_testline(self, testline_config_index=0):
        """
        :param testline_config_index:
        :return:
        """
        (
            enb_pdu_ip,
            enb_pdu_type,
            enb_pdu_port,
            iphy_pdu_ip,
            iphy_pdu_type,
            iphy_pdu_port,
        ) = self.get_testline_pdu_details(testline_config_index)

        tl = BuiltIn().get_variable_value("${tl}")
        kwargs = {}
        if isinstance(tl, TestLine):
            try:
                kwargs["login"] = tl.pdus[0].login
                kwargs["password"] = tl.pdus[0].password
            except Exception:
                pass

        self._pdu_interface.setup_pdu(alias='fsm', host=str(enb_pdu_ip), model=str(enb_pdu_type), **kwargs)
        self._pdu_interface.setup_pdu(alias='iphy', host=str(iphy_pdu_ip), model=str(iphy_pdu_type), **kwargs)

        self._pdu_interface.reset_ports(pdu_device='fsm', ports=[int(enb_pdu_port)])
        self._pdu_interface.reset_ports(pdu_device='iphy', ports=[int(iphy_pdu_port)])

    def print_status_of_the_cables(self):
        try:
            self._status_of_the_cables(port_number='15', eif='-EIF2')
            self._status_of_the_cables(port_number='14', eif='-EIF1')
        except Exception:
            pass

    def _status_of_the_cables(self, port_number, eif):
        output_gnb, code_gnb = ta5g_enb.ta5g_enb().execute_enb_command(cmd='dbgrrc show port {}'.format(port_number), return_rc=True)
        output_gnb_phy, code_gnb_phy = ta5g_enb.ta5g_enb().execute_enb_command(cmd='dbgrrc phy status port {}'.format(port_number), return_rc=True)
        output_ap, code_ap = ta5g_iphy.ta5g_iphy().execute_wts_command(cmd='dbgrrc show port {}'.format(port_number), return_rc=True)
        output_ap_phy, code_ap_phy = ta5g_iphy.ta5g_iphy().execute_wts_command(cmd='dbgrrc phy status port {}'.format(port_number), return_rc=True)
        self._print_with_color(red_text="Output of gNB command 'dbgrrc show port {}{}'".format(port_number, eif), text=output_gnb)
        self._print_with_color(red_text="Output of gNB command 'dbgrrc phy status port {}{}'".format(port_number, eif), text=output_gnb_phy)
        self._print_with_color(red_text="Output of airphone command 'dbgrrc show port {}{}'".format(port_number, eif), text=output_ap)
        self._print_with_color(red_text="Output of airphone command 'dbgrrc phy status port {}{}'".format(port_number, eif), text=output_ap_phy)

        self._print_with_color(red_text="Return code of gNB command 'dbgrrc show port {}{}'".format(port_number, eif), text=code_gnb)
        self._print_with_color(red_text="Return code of gNB command 'dbgrrc phy status port {}{}'".format(port_number, eif), text=code_gnb_phy)
        self._print_with_color(red_text="Return code of airphone command 'dbgrrc show port {}{}'".format(port_number, eif), text=code_ap)
        self._print_with_color(red_text="Return code of airphone command 'dbgrrc phy status port {}{}'".format(port_number, eif), text=code_ap_phy)

    @staticmethod
    def _print_with_color(red_text, text):
        logger.write(
            '<strong style="color:red">{}</strong></b>'.format(red_text),
            level='HTML',
            html=True,
        )
        logger.write('\n' + str(text) + '\n\n')

    @staticmethod
    def _determine_testline_config_directory_and_import_variables():
        hostname = socket.gethostname().replace("-", "_")
        config_path = glob("/home/ute/testline_configuration/{}".format(hostname))
        if len(config_path) == 1:
            config_path = config_path[0]
            logger.debug("Found testline configuration path: {}.".format(config_path))
            BuiltIn().import_variables(config_path)
        elif len(config_path) > 1:
            logger.debug("Found more configuration paths than one: {}.".format(config_path))

        else:
            logger.debug("Can't find testline configuration for hostname {}.".format(hostname))
